package com.mohymods.kingdomsmp.equipment;
import com.mohymods.kingdomsmp.economy.CommerceService;
import com.mohymods.kingdomsmp.network.*;
import com.mohymods.kingdomsmp.profession.FarmerInventoryExchange;
import net.minecraft.core.*;
import net.minecraft.core.particles.DustParticleOptions;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import org.joml.Vector3f;
import java.io.IOException;
import java.util.*;
/** Server-derived bounded selection and real material transaction. No coordinates or counts come from the client. */
public final class MasterWandService {
 enum Mode { LINE,WALL,FLOOR,REPLACE }
 private record Anchor(ServerLevel level,BlockPos at,Mode mode){ }
 private record Plan(ServerLevel level,Mode mode,ListTag cells,List<ItemStack> before,List<ItemStack> after,long revision,UUID nonce,long issued,String detail){ }
 private static final Map<ServerPlayer,Mode> MODES=new WeakHashMap<>();
 private static final Map<ServerPlayer,Anchor> ANCHORS=new WeakHashMap<>();
 private static final Map<ServerPlayer,Plan> PLANS=new WeakHashMap<>();
 private MasterWandService(){ }
 public static boolean active(ServerPlayer p){return PLANS.containsKey(p);}
 public static void close(ServerPlayer p){PLANS.remove(p);ANCHORS.remove(p);}
 public static void cycle(ServerPlayer p){if(!p.isShiftKeyDown()){p.sendSystemMessage(Component.literal("Wand: hold material in offhand. Click two corners to preview; sneak-right-click air cycles LINE/WALL/FLOOR/REPLACE. Look north/south or east/west to rotate walls."));return;}Mode m=Mode.values()[(MODES.getOrDefault(p,Mode.LINE).ordinal()+1)%Mode.values().length];MODES.put(p,m);close(p);p.displayClientMessage(Component.literal("Architect's Wand: "+m),true);}
 public static boolean plain(BlockState state,ServerLevel level,BlockPos at){var id=BuiltInRegistries.BLOCK.getKey(state.getBlock());return !state.isAir()&&id.getNamespace().equals("minecraft")&&!state.hasBlockEntity()&&state.getFluidState().isEmpty()&&state.isCollisionShapeFullBlock(level,at)&&state.equals(state.getBlock().defaultBlockState())&&(state.is(net.minecraft.tags.BlockTags.PLANKS)||state.is(net.minecraft.tags.BlockTags.WOOL)||Set.of("stone","cobblestone","stone_bricks","bricks","deepslate","cobbled_deepslate","deepslate_bricks","sandstone","smooth_sandstone","granite","diorite","andesite","polished_granite","polished_diorite","polished_andesite","glass").contains(id.getPath())||id.getPath().endsWith("_concrete"));}
 public static void select(ServerPlayer p,UseOnContext context){try{if(!p.getMainHandItem().is(MasterGearItems.item(MasterGear.WAND)))return;var mode=MODES.getOrDefault(p,Mode.LINE);var at=mode==Mode.REPLACE?context.getClickedPos():context.getClickedPos().relative(context.getClickedFace());if(!MasterToolService.permitted(p,at))throw new IllegalStateException("Wand site is not loaded/permitted or intersects kingdom property");var anchor=ANCHORS.get(p);if(anchor==null||anchor.level()!=p.serverLevel()||anchor.mode()!=mode){close(p);ANCHORS.put(p,new Anchor(p.serverLevel(),at.immutable(),mode));p.sendSystemMessage(Component.literal("Wand anchor selected: "+mode+". Click the opposite corner; offhand selects real material."));return;}var plan=plan(p,anchor,at);PLANS.put(p,plan);ANCHORS.remove(p);preview(p,plan);MasterStationService.close(p);CommerceNetworking.open(p,7);}catch(IllegalStateException|IllegalArgumentException failure){p.sendSystemMessage(Component.literal(failure.getMessage()));}}
 private static Plan plan(ServerPlayer p,Anchor anchor,BlockPos end){var held=p.getOffhandItem();if(!(held.getItem() instanceof BlockItem material))throw new IllegalStateException("Hold the selected plain building material in your offhand");var level=p.serverLevel();var target=material.getBlock().defaultBlockState();if(!ItemStack.isSameItemSameComponents(held,new ItemStack(material))||!plain(target,level,end))throw new IllegalStateException("Use supported plain full-cube masonry, planks, wool, glass or concrete");var start=anchor.at();int dx=Math.abs(end.getX()-start.getX()),dy=Math.abs(end.getY()-start.getY()),dz=Math.abs(end.getZ()-start.getZ());if(Math.max(dx,Math.max(dy,dz))>16)throw new IllegalStateException("Each selection axis is limited to16blocks");BlockPos last=end;switch(anchor.mode()){case FLOOR->last=new BlockPos(end.getX(),start.getY(),end.getZ());case WALL->last=p.getDirection().getAxis()==Direction.Axis.X?new BlockPos(start.getX(),end.getY(),end.getZ()):new BlockPos(end.getX(),end.getY(),start.getZ());case LINE->{if(dx>=dy&&dx>=dz)last=new BlockPos(end.getX(),start.getY(),start.getZ());else if(dy>=dz)last=new BlockPos(start.getX(),end.getY(),start.getZ());else last=new BlockPos(start.getX(),start.getY(),end.getZ());}case REPLACE->{}}
  long volume=(long)(Math.abs(last.getX()-start.getX())+1)*(Math.abs(last.getY()-start.getY())+1)*(Math.abs(last.getZ()-start.getZ())+1);if(volume>MasterGearRules.get(p.server).wandLimit())throw new IllegalStateException("Selection exceeds configured operation size");var match=level.getBlockState(start);if(anchor.mode()==Mode.REPLACE&&!plain(match,level,start))throw new IllegalStateException("Replace only matching plain building blocks; never terrain valuables or containers");var cells=new ListTag();for(var pos:BlockPos.betweenClosed(start,last)){var before=level.getBlockState(pos);if(anchor.mode()==Mode.REPLACE&&!before.equals(match))continue;if(before.equals(target))continue;if(!MasterToolService.permitted(p,pos)||anchor.mode()!=Mode.REPLACE&&!before.isAir()||!level.getEntities(null,new net.minecraft.world.phys.AABB(pos)).isEmpty())throw new IllegalStateException("Blocked or unpermitted cell: "+pos.toShortString());var row=new CompoundTag();row.putLong("position",pos.asLong());row.put("before",NbtUtils.writeBlockState(before));row.put("after",NbtUtils.writeBlockState(target));cells.add(row);}if(cells.isEmpty())throw new IllegalStateException("No eligible changed cells");
  var before=MasterWorkTransaction.inventory(p);var after=new ArrayList<>(before.stream().map(ItemStack::copy).toList());int left=cells.size();var offhand=p.getOffhandItem(); // Only main-inventory supplies are debited; offhand is a material selector.
  after=new ArrayList<>(FarmerInventoryExchange.plan(after,Map.of(material,left),Map.of()));String detail="Place "+cells.size()+" "+target.getBlock().getName().getString()+" blocks in "+anchor.mode()+" mode; consume exactly that many plain main-inventory blocks. Offhand selects material. "+(anchor.mode()==Mode.REPLACE?"Reviewed matching old blocks are permanently replaced without item refunds. ":"")+"Every site, claim and inventory is revalidated. A rejected operation rolls back as a whole; interrupted saves use canonical world/player recovery.";return new Plan(level,anchor.mode(),cells,List.copyOf(before),List.copyOf(after),CommerceService.store(p.server).revision(),UUID.randomUUID(),System.nanoTime(),detail);
 }
 private static void preview(ServerPlayer p,Plan plan){for(var value:plan.cells()){var at=BlockPos.of(((CompoundTag)value).getLong("position"));p.serverLevel().sendParticles(p,new DustParticleOptions(new Vector3f(.2f,1,.35f),1),true,at.getX()+.5,at.getY()+.5,at.getZ()+.5,8,.4,.4,.4,0);}}
 public static CommerceView view(ServerPlayer p,long request,String notice){var plan=PLANS.get(p);if(plan==null||p.serverLevel()!=plan.level()||!p.getMainHandItem().is(MasterGearItems.item(MasterGear.WAND)))throw new IllegalStateException("Hold the reviewed Wand in its original dimension");var s=CommerceService.store(p.server);return new CommerceView(request,s.revision(),false,7,com.mohymods.kingdomsmp.contribution.ContributionService.kingdom(p.server).attainedTier(),s.balance(p.getUUID()),List.of(new CommerceView.Entry("wand:review","Architect's Wand preview",plan.cells().size()+" validated placements. Green particles show every target cell. Review consumes nothing; Cancel leaves materials unchanged.",0,"EQUIPMENT")),plan.nonce(),plan.detail(),notice.isBlank()?"Architect's Wand — "+plan.mode():notice);}
 public static CommerceView handle(ServerPlayer p,CommerceRequest request)throws IOException{var plan=PLANS.get(p);if(request.action()!=2)throw new IllegalStateException("Use the displayed confirmation or close to cancel");PLANS.remove(p);if(plan==null||!plan.nonce().equals(request.review())||plan.revision()!=CommerceService.store(p.server).revision()||System.nanoTime()-plan.issued()>30_000_000_000L||p.serverLevel()!=plan.level()||!p.getMainHandItem().is(MasterGearItems.item(MasterGear.WAND)))throw new IllegalStateException("Wand review expired/changed");MasterWorkTransaction.commit(p,plan.nonce(),MasterGear.WAND,plan.before(),plan.after(),0,plan.cells());p.sendSystemMessage(Component.literal("Architect's Wand: "+plan.cells().size()+" blocks committed with real materials."));return CommerceService.snapshot(p,request.requestId(),7,"Wand construction completed");}
}
